<script setup lang="ts">
import { uiText, uiLocale } from '@/i18n'

import { computed,onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { researchApi,type Hit,type Source,type SearchFilters } from '@/api/research'
import { personalApi } from '@/api/personal'
import { authStore } from '@/stores/auth'
import { createRequestGuard } from '@/lib/requestGuard'
import type { PersonalAiPreview,PersonalAiSetting } from '@/types/personal'
import WorkspaceTasks from '@/components/WorkspaceTasks.vue'
import ReadingClips from '@/components/ReadingClips.vue'
import DocumentLibrary from '@/components/DocumentLibrary.vue'
import StudyCards from '@/components/StudyCards.vue'
import KnowledgeCollections from '@/components/KnowledgeCollections.vue'
import BenchmarkPanel from '@/components/BenchmarkPanel.vue'
import RecoveryPanel from '@/components/RecoveryPanel.vue'
import SearchHighlight from '@/components/SearchHighlight.vue'
import SavedSearches from '@/components/SavedSearches.vue'
const route=useRoute(),router=useRouter(),tab=computed(()=>String(route.query.tab||'search'))
const tabs=[['search','资料搜索与问答'],['documents','文档阅读'],['clips','阅读摘录'],['tasks','任务与同步'],['bookmarks','我的收藏'],['cards','复习卡'],['collections','资料表'],['evaluations','模型评测'],['trash','回收站与备份']]
const q=ref(''),type=ref('ALL'),tag=ref(''),since=ref(''),group=ref(''),sort=ref('relevance'),page=ref(0),hasMore=ref(false),appliedQuery=ref('')
const hits=ref<Hit[]>([]),selected=ref<Hit[]>([]),source=ref<Source|null>(null),error=ref(''),busy=ref(false),answerBusy=ref(false),question=ref(''),provider=ref(''),settings=ref<PersonalAiSetting[]>([]),preview=ref<PersonalAiPreview|null>(null),answer=ref(''),consent=ref(false)
const bookmarkKeys=ref(new Set<string>()),bookmarkBusy=ref(new Set<string>())
const searchGuard=createRequestGuard(),sourceGuard=createRequestGuard(),answerGuard=createRequestGuard(),settingsGuard=createRequestGuard(),shelfGuard=createRequestGuard()
let disposed=false,routeEpoch=0
const kinds=[['ALL','全部资料'],['NOTE','笔记'],['ENTRY','知识卡'],['FILE','附件名称'],['DOCUMENT','文档正文'],['RESULT','图片识别文字'],['TASK','实验结果'],['GROUP','群组资料']]
const filters=computed<SearchFilters>(()=>({q:q.value,type:type.value,tag:tag.value,since:since.value?new Date(since.value).toISOString():null,group:group.value?Number(group.value):null,sort:sort.value}))
const key=(h:Pick<Hit,'kind'|'id'>)=>h.kind+':'+h.id
const selectedKeys=computed(()=>new Set(selected.value.map(key)))
const kindName=(kind:string)=>kinds.find(k=>k[0]===kind)?.[1]||kind
function resetAnswer(){answerGuard.cancel();answerBusy.value=false;preview.value=null;consent.value=false;answer.value=''}
watch([question,provider,selected],resetAnswer,{deep:true})
async function search(){const request=searchGuard.start();busy.value=true;error.value='';sourceGuard.cancel();source.value=null
 try{const params:Record<string,string>={q:q.value,type:type.value,tag:tag.value,sort:sort.value,page:String(page.value)};if(since.value)params.since=new Date(since.value).toISOString();if(group.value)params.group=group.value
 const result=tab.value==='bookmarks'?await researchApi.bookmarks(page.value,request.signal):await researchApi.search(params,request.signal)
 if(request.current()){hits.value=result.items;hasMore.value=result.hasMore;appliedQuery.value=tab.value==='bookmarks'?'':q.value}}
 catch(e){if(request.current())error.value=(e as Error).message}finally{if(request.current())busy.value=false}}
async function submit(){page.value=0;const query:Record<string,string>={tab:'search',q:q.value,type:type.value,tag:tag.value,since:since.value,group:group.value,sort:sort.value},before=route.fullPath;await router.replace({path:'/app/research',query});if(route.fullPath===before)await search()}
async function apply(f:SearchFilters){q.value=f.q;type.value=f.type;tag.value=f.tag;since.value=f.since?.slice(0,10)||'';group.value=f.group?String(f.group):'';sort.value=f.sort;await submit()}
function toggle(h:Hit){const i=selected.value.findIndex(s=>key(s)===key(h));if(i>=0)selected.value.splice(i,1);else if(selected.value.length<8)selected.value.push(h)}
async function view(h:Pick<Hit,'kind'|'id'>){const request=sourceGuard.start();error.value='';source.value=null;try{const result=await researchApi.source(h.kind,h.id,request.signal);if(request.current())source.value=result}catch(e){if(request.current())error.value=(e as Error).message}}
function selectSource(){if(source.value)toggle({...source.value,excerpt:source.value.body.slice(0,200)})}
function closeSource(){sourceGuard.cancel();source.value=null}
async function bookmark(h:Pick<Hit,'kind'|'id'>){const id=key(h);if(bookmarkBusy.value.has(id))return;bookmarkBusy.value.add(id);error.value='';try{if(bookmarkKeys.value.has(id)){await researchApi.removeBookmark(h.kind,h.id);if(!disposed){bookmarkKeys.value.delete(id);if(tab.value==='bookmarks')await search()}}else{await researchApi.bookmark(h.kind,h.id);if(!disposed)bookmarkKeys.value.add(id)}}catch(e){if(!disposed)error.value=(e as Error).message}finally{bookmarkBusy.value.delete(id)}}
async function ask(){if(answerBusy.value)return;const request=answerGuard.start();answerBusy.value=true;error.value='';answer.value='';try{const result=await researchApi.preview(provider.value,question.value,selected.value,request.signal);if(request.current()){preview.value=result;consent.value=false}}catch(e){if(request.current())error.value=(e as Error).message}finally{if(request.current())answerBusy.value=false}}
async function execute(){if(!preview.value||!consent.value||answerBusy.value)return;const request=answerGuard.start();answerBusy.value=true;error.value='';try{const result=await researchApi.answer(preview.value.previewToken,request.signal);if(request.current()){answer.value=result.result;preview.value=null}}catch(e){if(request.current()){error.value=(e as Error).message;preview.value=null}}finally{if(request.current())answerBusy.value=false}}
async function capture(){if(!source.value||busy.value)return;busy.value=true;try{const note=await researchApi.capture(source.value.kind,source.value.id);if(!disposed)void router.push('/app/notes/'+note.id+'/edit')}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function routeChanged(){const epoch=++routeEpoch;searchGuard.cancel();closeSource();busy.value=false;if(!['search','bookmarks'].includes(tab.value))return;q.value=String(route.query.q||'');type.value=String(route.query.type||'ALL');tag.value=String(route.query.tag||'');since.value=String(route.query.since||'');group.value=String(route.query.group||'');sort.value=String(route.query.sort||'relevance');page.value=0;await search();if(!disposed&&epoch===routeEpoch&&route.query.source)await view({kind:String(route.query.type||'NOTE'),id:String(route.query.source)})}
async function cleanup(){if(busy.value)return;busy.value=true;try{await researchApi.cleanupBookmarks();if(!disposed){await loadShelf();await search()}}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function loadShelf(){const request=shelfGuard.start();try{const keys=await researchApi.bookmarkKeys(request.signal);if(request.current())bookmarkKeys.value=new Set(keys.map(key))}catch(e){if(request.current())error.value=(e as Error).message}}
async function initial(){void loadShelf();if(authStore.has('personal-ai:use')){const request=settingsGuard.start();try{const result=await personalApi.settings();if(request.current()){settings.value=result.filter(s=>s.configured&&s.enabled);provider.value=settings.value[0]?.provider||''}}catch{/* Settings link remains available. */}}}
watch(()=>route.fullPath,routeChanged,{immediate:true});onMounted(initial)
onBeforeUnmount(()=>{disposed=true;[searchGuard,sourceGuard,answerGuard,settingsGuard,shelfGuard].forEach(g=>g.cancel())})
</script>
<template>
 <div class="research-space"><header class="research-intro"><p class="page-kicker">LEARNING WORKSPACE</p><h1>{{ uiText('让资料成为自己的知识。') }}</h1><p>{{ uiText('检索、整理、复习与验证，都从这里继续。') }}</p></header>
 <nav class="research-tabs" :aria-label="uiText('学习中心')"><RouterLink v-for="t in tabs" :key="t[0]" :to="{path:'/app/research',query:{tab:t[0]}}" :aria-current="tab===t[0]?'page':undefined">{{ uiText(t[1]) }}</RouterLink></nav>
 <template v-if="tab==='search'||tab==='bookmarks'">
 <template v-if="tab==='search'"><form class="research-filters" @submit.prevent="submit"><input v-model="q" class="field-input" :aria-label="uiText('搜索资料')" :placeholder="uiText('输入关键词，或选择自然语句检索')" maxlength="160"/><select v-model="type" class="field-input" :aria-label="uiText('资料类型')"><option v-for="k in kinds" :key="k[0]" :value="k[0]">{{ uiText(k[1]) }}</option></select><input v-model="tag" class="field-input" :aria-label="uiText('标签')" :placeholder="uiText('标签')" maxlength="80"/><input v-model="since" type="date" class="field-input" :aria-label="uiText('起始日期')"/><select v-model="sort" class="field-input" :aria-label="uiText('搜索排序')"><option value="semantic">{{uiText('语义关联（本地）')}}</option><option value="natural">{{ uiText('自然语句（本地扩展）') }}</option><option value="relevance">{{ uiText('相关性优先') }}</option><option value="recent">{{ uiText('最近更新') }}</option></select><button class="button button--dark" :disabled="busy">{{ busy?uiText('搜索中…'):uiText('搜索') }}</button></form><p v-if="sort==='semantic'" class="research-hint">{{uiText('本地语义关联从有权限的资料中选取最多 160 份候选，分析词语共现关系。不会发送资料；未收录的表达可以改用关键词查找。')}}</p><SavedSearches :filters="filters" @apply="apply"/></template>
 <div v-else class="research-section-title"><p class="research-hint">{{ uiText('收藏常用笔记、知识卡、识别结果和群组资料。内容更新后，这里会显示最新版本。') }}</p><button class="button button--ghost" :disabled="busy" :title="uiText('移除已经删除或当前没有访问权限的收藏')" @click="cleanup">{{ uiText('清理失效收藏') }}</button></div>
 <p v-if="error" role="alert" class="inline-alert inline-alert--error">{{ uiText(error) }}</p>
 <div class="research-columns"><section :aria-busy="busy"><div class="research-section-title"><h2>{{ tab==='bookmarks'?uiText('我的收藏'):uiText('搜索结果') }}</h2><small>{{ busy?uiText('正在加载…'):uiText('选择最多 8 份资料用于问答') }}</small></div><p v-if="!hits.length&&!busy" class="research-empty">{{ tab==='bookmarks'?uiText('还没有可查看的收藏。在搜索结果中点「收藏」，下次就能从这里打开。'):uiText('没有找到资料。试试更短的关键词或其他类型。') }}</p>
 <article v-for="h in hits" :key="key(h)" class="search-result"><input type="checkbox" :checked="selectedKeys.has(key(h))" :disabled="answerBusy||selected.length>=8&&!selectedKeys.has(key(h))" :aria-label="'选择 '+h.title" @change="toggle(h)"/><div><small>{{ uiText(kindName(h.kind)) }} · {{ new Date(h.updatedAt).toLocaleDateString(uiLocale()) }}</small><button class="result-title" :aria-label="h.title" @click="view(h)"><SearchHighlight :text="h.title" :query="appliedQuery"/></button><p><SearchHighlight :text="h.excerpt" :query="appliedQuery"/></p></div><button class="bookmark-button" :class="{'is-saved':bookmarkKeys.has(key(h))}" :aria-pressed="bookmarkKeys.has(key(h))" :aria-label="(bookmarkKeys.has(key(h))?uiText('取消收藏 '):uiText('收藏 '))+h.title" :disabled="bookmarkBusy.has(key(h))" @click="bookmark(h)">{{ bookmarkKeys.has(key(h))?uiText('已收藏'):uiText('收藏') }}</button></article>
 <div class="research-pagination"><button class="button button--ghost" :disabled="page===0||busy" @click="page--;search()">{{ uiText('上一页') }}</button><span>{{ page+1 }}</span><button class="button button--ghost" :disabled="!hasMore||busy" @click="page++;search()">{{ uiText('下一页') }}</button></div>
 <section v-if="source" class="source-reader"><div class="research-section-title"><h2>{{ source.title }}</h2><button class="button button--ghost" @click="closeSource">{{ uiText('收起') }}</button></div><pre>{{ source.body }}</pre><div class="research-actions"><RouterLink v-if="!['RESULT','GROUP'].includes(source.kind)" :to="source.url">{{ uiText('打开原始资料 →') }}</RouterLink><button v-if="authStore.has('personal-ai:use')" class="button button--ghost" :disabled="answerBusy" @click="selectSource">{{selectedKeys.has(key(source))?uiText('取消问答引用'):uiText('用于提问')}}</button><button class="button button--ghost" :disabled="bookmarkBusy.has(key(source))" @click="bookmark(source)">{{ bookmarkKeys.has(key(source))?uiText('取消收藏'):uiText('收藏资料') }}</button><button v-if="authStore.has('note:write')" class="button button--ghost" :disabled="busy" @click="capture">{{ uiText('存为新笔记') }}</button><RouterLink :to="{path:'/app/research',query:{tab:'cards',source:source.id,type:source.kind}}">{{ uiText('制作复习卡 →') }}</RouterLink></div></section>
 </section><aside v-if="authStore.has('personal-ai:use')&&authStore.has('note:write')" class="research-answer"><h2>{{ uiText('向自己的资料提问') }}</h2><p class="research-hint">{{ uiText('先选择资料，再预览发送范围。回答会标注来源编号。') }}</p><div class="source-chips"><button v-for="(s,i) in selected" :key="key(s)" :disabled="answerBusy" @click="toggle(s)">S{{ i+1 }} · {{ s.title }} ×</button></div><textarea v-model="question" class="field-input" :disabled="answerBusy" rows="4" maxlength="1000" :placeholder="uiText('例如：这些资料中，哪种方法适合我的实验？')" :aria-label="uiText('问题')"/><select v-model="provider" class="field-input" :disabled="answerBusy" :aria-label="uiText('问答供应商')"><option value="">{{ uiText('选择个人 AI') }}</option><option v-for="s in settings" :key="s.provider" :value="s.provider">{{ s.provider }} · {{ s.model }}</option></select><RouterLink v-if="!settings.length" to="/app/settings?section=ai">{{ uiText('先配置个人 AI →') }}</RouterLink><button class="button button--dark" :disabled="answerBusy||!provider||!selected.length||!question.trim()" @click="ask">{{ uiText('预览发送内容') }}</button>
 <section v-if="preview" class="answer-preview"><strong>{{ preview.provider }} · {{ preview.model }}</strong><pre>{{ preview.context }}</pre><label><input v-model="consent" type="checkbox" :disabled="answerBusy"/>{{ uiText('确认发送这些资料，使用我的个人密钥调用') }}</label><button class="button button--dark" :disabled="answerBusy||!consent" @click="execute">{{ answerBusy?uiText('回答生成中…'):uiText('确认并提问') }}</button></section><section v-if="answer" class="answer-output"><h3>{{ uiText('回答') }}</h3><pre>{{ answer }}</pre><ol><li v-for="s in selected" :key="key(s)"><button class="result-title" @click="view(s)">{{ s.title }}</button></li></ol></section></aside><aside v-else class="research-answer"><h2>{{ uiText('继续整理资料') }}</h2><p class="research-hint">{{ uiText('打开资料后，可以继续编写笔记或制作复习卡。') }}</p><RouterLink to="/app/research?tab=cards">{{ uiText('打开复习卡 →') }}</RouterLink></aside></div></template>
 <WorkspaceTasks v-if="tab==='tasks'"/><ReadingClips v-if="tab==='clips'"/><DocumentLibrary v-if="tab==='documents'" />
 <StudyCards v-else-if="tab==='cards'"/><KnowledgeCollections v-else-if="tab==='collections'"/><BenchmarkPanel v-else-if="tab==='evaluations'"/><RecoveryPanel v-else-if="tab==='trash'"/>
 </div>
</template>
